assertions.value:
import subprocess, sys
r = subprocess.run([sys.executable, 'service.py'], capture_output=True, text=True)
assert r.returncode == 0, r.stderr
from service import deposit, withdraw
for fn in (deposit, withdraw):
    try:
        fn(10, 0)
    except ValueError:
        pass
    else:
        raise AssertionError(f'{fn.__name__} accepted 0')
    try:
        fn(10, -5)
    except ValueError:
        pass
    else:
        raise AssertionError(f'{fn.__name__} accepted a negative amount')
assert deposit(10, 5) == 15 and withdraw(10, 5) == 5
print('OK')
